import type { ComponentPropsWithoutRef } from "react";
import { cn } from "../../lib/cn";
import "../../styles/link.css";

export interface LinkProps extends ComponentPropsWithoutRef<"a"> {
  /** When the underline shows. "hover" keeps body text calm. */
  underline?: "always" | "hover" | "none";
}

/**
 * Inline link. Uses the accent for color and an offset underline, so the
 * text stays readable on any brand color.
 */
export function Link({ underline = "always", className, children, ...props }: LinkProps) {
  return (
    <a className={cn("eui-link", `eui-link--${underline}`, className)} {...props}>
      {children}
    </a>
  );
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Link. The underline is offset and thin, and it is set with text-decoration
   so the text keeps its own color. Focus uses the shared ring. */

.eui-link {
  color: var(--eui-color-accent);
  text-decoration-line: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  text-decoration-color: color-mix(in oklab, currentColor 40%, transparent);
  border-radius: var(--eui-radius-sm);
  transition: text-decoration-color var(--eui-duration-fast) var(--eui-easing-out);
}

.eui-link--always {
  text-decoration-color: currentColor;
}

.eui-link--hover {
  text-decoration-line: none;
}

.eui-link--hover:hover {
  text-decoration-line: underline;
  text-decoration-color: currentColor;
}

.eui-link--none {
  text-decoration-line: none;
}

.eui-link:hover {
  text-decoration-color: currentColor;
}

.eui-link:focus-visible {
  outline: 2px solid var(--eui-color-ring);
  outline-offset: 2px;
}
